class Cat {
    String name;

    Cat(String name) {
        this.name = name;
    }
}

public class Main {
    public static void main(String[] args) {
        Cat 招牌猫 = new Cat("{n}");
        System.out.println("招牌上写着：" + 招牌猫.name);
        招牌猫 = null;
    }
}
